	@Test
	void orderedWrapperForwardsAllChildrenWithoutClaimingPartialOwnership() {
		var first = mock(RecordIterator.class);
		var second = mock(RecordIterator.class);
		when(first.getIndexName()).thenReturn("spoc");
		when(second.getIndexName()).thenReturn("spoc");
		when(first.next()).thenReturn(new long[] { 1, 2, 3, 4 }, (long[]) null);
		when(second.next()).thenReturn(new long[] { 2, 2, 3, 4 }, (long[]) null);
		var owner = new NativeRecordCancellation(new NativeCancellationToken(), null, CancellationSignal.NONE);
		when(first.bindCancellation(owner)).thenReturn(true);
		when(second.bindCancellation(owner)).thenReturn(false);
		when(first.requestCancellation()).thenReturn(true);
		try (var merged = OrderedRecordIterator.merge(java.util.List.of(first, second), StatementOrder.S)) {
			assertThat(merged.bindCancellation(owner)).isFalse();
			verify(first).bindCancellation(owner);
			verify(second).bindCancellation(owner);
			assertThat(merged.requestCancellation()).isTrue();
			verify(first).requestCancellation();
			verify(second).requestCancellation();
		}
	}

